import json, re, shlex

def render(source, data):
    # Handle the common control blocks while preserving the exact literal text.
    def resolve(expr):
        expr=expr.strip()
        if expr in (".", "$"): return data
        if expr.startswith("."):
            v=data
            for part in expr[1:].split("."):
                if not part: continue
                if isinstance(v,dict): v=v.get(part, "")
                else: v=getattr(v,part,"")
            return v
        if expr.startswith('"') and expr.endswith('"'):
            try:return json.loads(expr)
            except:return expr[1:-1]
        if expr in ("true","false"): return expr=="true"
        if expr.isdigit(): return int(expr)
        return expr
    def stringify(v):
        if v is None:return "<no value>"
        if isinstance(v,bool):return str(v).lower()
        if isinstance(v,(dict,list)):return json.dumps(v,ensure_ascii=False,separators=(",",":"))
        return str(v)
    def evaluate(e):
        e=e.strip()
