                vals=[resolve(x) for x in args[1:]]
                value=fmt % tuple(vals) if len(vals)!=1 else fmt % vals[0]
            except Exception:value=""
        elif value_expr.startswith("toJson "):
            value=json.dumps(resolve(value_expr[7:]),ensure_ascii=False,separators=(",",":"))
        elif value_expr.startswith("toPrettyJson "):
            value=json.dumps(resolve(value_expr[12:]),ensure_ascii=False,indent=2)
        elif value_expr.startswith("quote "):
            value=json.dumps(stringify(resolve(value_expr[6:])),ensure_ascii=False)
        elif value_expr.startswith("json "):
            value=json.dumps(stringify(resolve(value_expr[5:])),ensure_ascii=False)
        elif value_expr.startswith("upper "):
            value=stringify(resolve(value_expr[6:])).upper()
        elif value_expr.startswith("lower "):
            value=stringify(resolve(value_expr[6:])).lower()
        elif value_expr.startswith("trim "):
            value=stringify(resolve(value_expr[5:])).strip()
        else:value=resolve(value_expr)
        for fn in chunks[1:]:
            if fn=="toJson":value=json.dumps(value,ensure_ascii=False,separators=(",",":"))
            elif fn=="toPrettyJson":value=json.dumps(value,ensure_ascii=False,indent=2)
            elif fn=="quote":value=json.dumps(stringify(value),ensure_ascii=False)
            elif fn=="toString":value=stringify(value)
            elif fn=="toLower":value=stringify(value).lower()
            elif fn=="toUpper":value=stringify(value).upper()
            elif fn in ("upper", "toUpper"):value=stringify(value).upper()
            elif fn in ("lower", "toLower"):value=stringify(value).lower()
            elif fn=="trim":value=stringify(value).strip()
            elif fn=="base64Encode":
                import base64
                value=base64.b64encode(stringify(value).encode()).decode()
        return stringify(value)
    # Nested if/with/range blocks are not supported yet; simple if and else.
    pat=re.compile(r'{{-?\s*(.*?)\s*-?}}',re.S)
    tokens=list(pat.finditer(source)); out=[]; pos=0; active=[True]
    for m in tokens:
        if active[-1]:out.append(source[pos:m.start()])
        command=m.group(1).strip()
        if command.startswith("if "):
            condition=resolve(command[3:]); active.append(active[-1] and bool(condition))
        elif command=="else":
            if len(active)>1: active[-1]=active[-2] and not active[-1]
        elif command=="end":
