"""Small read-only implementations of chezmoi's unmanaged/ignored commands."""
import fnmatch
import os
from pathlib import Path


_ATTRS = ("private_", "executable_", "readonly_", "encrypted_", "empty_",
          "symlink_", "modify_", "create_", "remove_", "exact_",
          "run_once_", "run_onchange_", "run_before_", "run_after_", "run_")

def _source_metadata(name):
    return name in (".chezmoiignore", ".chezmoi.toml", ".chezmoi.toml.tmpl") or name.startswith(".chezmoidata.")


def target_name(name):
    # Attributes are source-state prefixes and are stripped in the target.
    changed = True
    while changed:
        changed = False
        for prefix in _ATTRS:
            if prefix.strip() and name.startswith(prefix.strip()):
                name = name[len(prefix.strip()):]
                changed = True
    if name.startswith("dot_"):
        name = "." + name[4:]
    if name.endswith(".tmpl"):
        name = name[:-5]
    return name


def _managed(source):
    result = set()
    root = Path(source)
    if not root.is_dir():
        return result
    for base, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d != ".git"]
        relbase = Path(base).relative_to(root)
        for name in dirs + files:
            if _source_metadata(name):
                continue
            # Run scripts are source-state actions, not destination entries.
            if name in files and name.startswith("run_"):
                continue
            if name in files and not name.startswith("empty_"):
                try:
                    if (root / name).stat().st_size == 0:
                        continue
                except OSError:
                    continue
            rel = Path(*(target_name(part) for part in relbase.parts), target_name(name)).as_posix()
            result.add(rel)
    return result


def _ignored_patterns(source):
    p = Path(source) / ".chezmoiignore"
    try:
        return [x.strip() for x in p.read_text().splitlines()
                if x.strip() and not x.lstrip().startswith("#")]
    except OSError:
        return []


def _tree_lines(paths):
    root = {}
    terminal = object()
    for path in paths:
        node = root
        for part in path.split("/"):
            node = node.setdefault(part, {})
        node[terminal] = None
    lines = []
    def walk(node, depth):
        for key in sorted((k for k in node if k is not terminal)):
            lines.append("  " * depth + key)
            walk(node[key], depth + 1)
    walk(root, 0)
    return lines


def handle(command, args, source, destination):
    """Return (exit status, stdout, stderr); args excludes command/global flags."""
    nul = "-0" in args or "--nul-path-separator" in args
    absolute = "--path-style=absolute" in args or "--path-style" in args and args[args.index("--path-style") + 1:args.index("--path-style") + 2] == ["absolute"]
    tree = "-t" in args or "--tree" in args
    includes = None
    excludes = set()
    operands = []
    j = 0
    while j < len(args):
        a = args[j]
        if a in ("--include", "-i", "--exclude", "-x", "--path-style", "-p") and j + 1 < len(args):
            key, val = a, args[j + 1]
            if key in ("--include", "-i"): includes = set(val.split(","))
            elif key in ("--exclude", "-x"): excludes.update(val.split(","))
            j += 2
            continue
        if a.startswith("--include="): includes = set(a.split("=", 1)[1].split(","))
        elif a.startswith("--exclude="): excludes.update(a.split("=", 1)[1].split(","))
        elif a.startswith("--path-style="): pass
        elif a.startswith("-"): pass
        else: operands.append(a)
        j += 1
    root = Path(destination).expanduser().resolve()
    if command == "unmanaged" and not root.exists():
        raw = os.fspath(root)
        return 1, "", f"chezmoi: {raw}: lstat {raw}: no such file or directory\nchezmoi: skip this directory\n"
    known = _managed(source)
    if command == "ignored":
        patterns = _ignored_patterns(source)
        candidates = []
        source_root = Path(source).expanduser()
        for base, dirs, files in os.walk(source_root):
            dirs.sort(); files.sort()
            for n in dirs + files:
                if _source_metadata(n):
                    continue
                src_rel = (Path(base) / n).relative_to(source_root)
                rel = Path(*(target_name(part) for part in src_rel.parts)).as_posix()
                if any(("/" not in rel or "/" in p) and fnmatch.fnmatchcase(rel, p)
                       for p in patterns):
                    candidates.append(rel)
        candidates.sort()
    else:
        candidates = []
        def visit(path):
            rel = path.relative_to(root).as_posix()
            # Managed directories are traversed so unmanaged descendants are
            # still reported. Unmanaged directories are reported as a unit.
            if path.is_dir() and not path.is_symlink() and rel in known:
                for child in sorted(path.iterdir()):
