def yaml_dump(value, indent=0):
    pad=' '*indent
    if isinstance(value,dict):
        lines=[]
        for key in sorted(value):
            val=value[key]
            k=str(key) if str(key).replace('_','').isalnum() else json.dumps(str(key),ensure_ascii=False)
            if isinstance(val,(dict,list)) and val:
                lines.append(pad+k+':')
                lines.append(yaml_dump(val,indent if isinstance(val,list) else indent+2).rstrip('\n'))
            else:
                lines.append(pad+k+': '+yaml_scalar(val))
        return '\n'.join(lines)+'\n'
    if isinstance(value,list):
        return ''.join(pad+'- '+yaml_scalar(x)+'\n' for x in value)
    return pad+yaml_scalar(value)+'\n'

def yaml_scalar(value):
    if value is None:return 'null'
    if isinstance(value,bool):return 'true' if value else 'false'
    if isinstance(value,(dict,list)):return json.dumps(value,ensure_ascii=False,separators=(',',':'))
    if isinstance(value,(int,float)):
        if isinstance(value,int) and abs(value)>=1_000_000_000:return format(value,'.0e')
        return str(value)
    s=str(value)
    import re
    ambiguous=bool(re.fullmatch(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?',s))
    if not s or s.strip()!=s or ambiguous or s==':' or s.lower() in ('null','true','false','yes','no') or re.match(r'^[{}\[\],&*#?!|>\'"%@`]',s) or ': ' in s or ' #' in s:
